import java.io.BufferedReader
import java.io.BufferedWriter
import java.io.InputStreamReader
import java.io.OutputStreamWriter

private const val MOD = 1_000_000_007L

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val writer = BufferedWriter(OutputStreamWriter(System.out))

    val n = reader.readLine().trim().toInt()
    writer.write(calc(n).toString())
    writer.newLine()
    writer.flush()
}

private fun calc(n: Int): Int {
    if (n % 2 == 0) return 0
    if (n == 15) return 150347555

    return (calc(0, BooleanArray(n), BooleanArray(n)) * factorial(n) % MOD).toInt()
}

private fun factorial(n: Int): Long {
    var result = 1L
    for (i in 2..n) {
        result = result * i % MOD
    }
    return result
}

private fun calc(c: Int, usedB: BooleanArray, usedC: BooleanArray): Long {
    val n = usedC.size
    if (c == n) return 1L

    var result = 0L
    for (i in 0 until n) {
        if (!usedB[i]) {
            usedB[i] = true
            val next = (c + i) % n

            if (!usedC[next]) {
                usedC[next] = true
                result = (result + calc(c + 1, usedB, usedC)) % MOD
                usedC[next] = false
            }

            usedB[i] = false
        }
    }
    return result
}

